package net.battlespades.bot;
import java.util.*;
import net.battlespades.physics.PlayerPhysics.Vector;
import static net.battlespades.bot.BotMessages.*;
import static net.battlespades.bot.BotState.*;
import static net.battlespades.bot.BotVectors.*;

/** Measured combat hops and validated flight phases, independent of authoritative native jump rearming. */
final class BrainMobility {
    private BrainMobility(){}
    record Flight(Movement movement,Look look,int tool,Vector goal,String role){}
    static boolean tacticalHop(BotNavigationWorld w,Perception f,Player p,BotBrainState s,Movement movement,double now){var profile=f.profile()==null?BrainInventory.fallback(p.id()):f.profile();if(!p.grounded()||p.wade()||movement.crouch()||movement.affordance()!=Affordance.WALK||profile.aggression()<.4||now<s.nextHopAt||p.reloading()||p.health()>75||p.lastDamageAt()<=s.lastHopDamageAt||now-p.lastDamageAt()<0||now-p.lastDamageAt()>.8||Math.hypot(movement.direction().x(),movement.direction().y())<.5)return false;for(double distance:new double[]{0,1,2,3,4}){double x=p.position().x()+movement.direction().x()*distance,y=p.position().y()+movement.direction().y()*distance;var surface=w.surface((int)x,(int)y,p.position().z(),1,false);if(surface==null||Math.abs(surface.position().z()-p.position().z())>.3)return false;for(double dx:new double[]{-.45,.45})for(double dy:new double[]{-.45,.45})for(int z=surface.supportZ()-5;z<surface.supportZ()-1;z++)if(w.solid((int)(x+dx),(int)(y+dy),z))return false;}s.lastHopDamageAt=p.lastDamageAt();s.nextHopAt=now+3.5+profile.caution()*2+(p.id()*.37)%.7;return true;}
    static Vector perch(BotNavigationWorld w,Player p,Player target){if(!p.grounded()||p.wade())return null;int x=(int)Math.floor(p.position().x()),y=(int)Math.floor(p.position().y()),support=(int)Math.rint(p.position().z()+2.25),bestRise=0;Vector best=null;for(var d:SchematicPlanning.CARDINAL){var surface=w.surface(x+d[0],y+d[1],p.position().z(),8,false);if(surface==null)continue;int rise=support-surface.supportZ();if(rise<3||rise>8||surface.supportZ()-4<1)continue;boolean clear=true;for(int z=surface.supportZ()-4;z<support;z++)if(w.solid(x,y,z)){clear=false;break;}if(!clear)continue;var point=surface.position();var eye=new Vector(point.x(),point.y(),point.z()+p.eye().z()-p.position().z());if(!w.lineOfSight(eye,target.eye()))continue;if(best==null||rise>bestRise){bestRise=rise;best=point;}}return best;}
    static void start(BotBrainState s,Player p,Player target,Vector landing,double now){s.flightStep=new RouteStep(landing,Affordance.JETPACK);s.flightSource=p.position();s.flightStartedAt=now;s.flightDeparted=false;s.flightWatch=target.eye();BrainRoutingState.setGoal(s,null,p.position(),now);}
    static boolean combatHop(BotNavigationWorld w,Perception f,Player p,Player target,BotBrainState s,BotProfile profile,double now){var abilities=BrainInventory.movementAbilities(p);if(now<s.nextCombatHopAt||now<s.nextFlightAt||!abilities.contains(Affordance.JETPACK)||distance(p.position(),target.position())<9)return false;boolean pressured=now-p.lastDamageAt()>=0&&now-p.lastDamageAt()<=1,climber=abilities.contains(Affordance.JETPACK_CLIMB);double whim=BotCombatTactics.mix(p.id(),p.lifeId(),(int)(now/2.5)),eagerness=.1+.25*profile.creativity()+(climber?.15:0);if(!pressured&&whim>eagerness)return false;s.nextCombatHopAt=now+2.5;if(climber){var perch=perch(w,p,target);if(perch!=null){s.engagement.relocations++;s.nextCombatHopAt=now+10+6*profile.caution();start(s,p,target,perch,now);return true;}}var heading=BotCombatTactics.relocationHeading(w,p,target,profile,s.engagement);if(heading==null)return false;s.engagement.relocations++;for(double reach:new double[]{7,5.5}){double x=p.position().x()+heading.x()*reach,y=p.position().y()+heading.y()*reach;var surface=w.surface((int)Math.floor(x),(int)Math.floor(y),p.position().z(),3,false);if(surface==null||Math.abs(surface.position().z()-p.position().z())>2.5)continue;var apex=new Vector(p.position().x(),p.position().y(),p.position().z()-3);if(!w.lineOfSight(p.eye(),apex)||!w.lineOfSight(apex,surface.position()))continue;s.nextCombatHopAt=now+9+6*profile.caution();start(s,p,target,surface.position(),now);return true;}return false;}
    static Flight flight(Player p,BotBrainState s,double now){var step=s.flightStep;var source=s.flightSource;if(step==null||source==null)return null;double elapsed=now-s.flightStartedAt,gap=flat(step.waypoint(),p.position());s.flightDeparted|=!p.grounded();boolean landed=s.flightDeparted&&p.grounded()&&elapsed>.35;double climbBudget=Math.max(0,source.z()-step.waypoint().z())*.3;if(landed||p.wade()||elapsed>=3.5+climbBudget){if(gap>1||p.wade()){var edge=new Edge(node(source),node(step.waypoint()));s.blockedEdges.put(edge,now+60);s.blockedEdgeSince.put(edge,now);}s.flightStep=null;s.flightSource=null;s.flightWatch=null;s.nextFlightAt=now+4;BrainRoutingState.clear(s,now);return null;}double altitude=source.z()-p.position().z(),climb=source.z()-step.waypoint().z(),rising=Math.max(0,-p.velocity().z()),coast=rising*rising/.086;var direction=unit(step.waypoint().x()-p.position().x(),step.waypoint().y()-p.position().y());boolean thrust;if(climb>1){if(altitude<climb+.6||gap<.4)direction=ZERO;thrust=(elapsed<.2||altitude+coast<climb+1.3)&&elapsed<2+climb*.3;}else{if(altitude<.8&&elapsed<.6||gap<.4)direction=ZERO;double ceiling=p.jetpackId()==68?5:2.5,takeoff=p.jetpackId()==66?.25:.5;thrust=elapsed<takeoff||altitude+coast<ceiling&&gap>.6&&elapsed<2.3;}return new Flight(new Movement(direction,false,false,false,false,Affordance.JETPACK,thrust,null,null,null,1),new Look(s.flightWatch==null?step.waypoint():s.flightWatch,false,-1,0,0,false),BrainInventory.weapon(p,null),step.waypoint(),(s.flightWatch==null?"":"combat_")+(thrust?"jetpack_takeoff":"jetpack_landing"));}
    static Cell node(Vector p){return new Cell((int)Math.floor(p.x()),(int)Math.floor(p.y()),(int)Math.floor(p.z()+2.25));}
}
